hu = [[-1000, -50, 20, 60],
      [-120, 0, 40, 120],
      [30, 45, 55, 900],
      [10, 35, 70, 3000]]


def pencerele(v, W, L):
    alt = L - W / 2.0
    if v <= alt:
        return 0
    if v >= alt + W:
        return 255
    return int((v - alt) / W * 255)


for satir in hu:
    print(" ".join("%3d" % pencerele(v, 80, 40) for v in satir))
print("---")
for satir in hu:
    print(" ".join("%3d" % pencerele(v, 2000, 300) for v in satir))
